// GERADO por scripts/gerar-extensao.mjs a partir de extensao-centi/ — não edite à mão (o teste confere).
// biome-ignore-all lint/suspicious/noTemplateCurlyInString: é o código-fonte da extensão, em texto.
export const ARQUIVOS_EXTENSAO: Record<string, string> = {
  "background.js": "// Serviço da extensão: leva o pedido da aba Automação à aba da Centi que tem a sessão e devolve o resultado.\n// Instala-se SOZINHO nas abas já abertas (ao instalar/atualizar e quando uma aba da Centi não responde) — sem F5 e sem\n// refazer o login: a sessão da Centi continua a da aba.\nconst CENTI = \"https://rioverde.centi.com.br/*\";\nconst SISTEMA = [\"https://governarv.com.br/painel/automacao*\", \"https://www.governarv.com.br/painel/automacao*\"];\nconst ORIGENS = [\"https://governarv.com.br\", \"https://www.governarv.com.br\"];\nconst CONFIRMAR = chrome.runtime.getURL(\"confirmar.html\");\n\nconst comPrazo = (p, ms, valor) => Promise.race([p, new Promise((ok) => setTimeout(() => ok(valor), ms))]);\n\nasync function injetarCenti(tabId) {\n  await chrome.scripting.executeScript({ target: { tabId }, files: [\"centi-anexo.js\", \"centi-main.js\"], world: \"MAIN\" });\n  await chrome.scripting.executeScript({ target: { tabId }, files: [\"centi-ponte.js\"] });\n}\n\nasync function estadoDaAba(tabId) {\n  const perguntar = () => comPrazo(chrome.tabs.sendMessage(tabId, { alvo: \"centi\", acao: \"estado\" }), 5000, null);\n  try {\n    const r = await perguntar();\n    if (r) return r;\n  } catch {}\n  try {\n    await injetarCenti(tabId);\n    return await perguntar();\n  } catch {\n    return null;\n  }\n}\n\n// A Centi faz login POR ABA: usa a aba que já tem a sessão.\nasync function abaCenti() {\n  const abas = await chrome.tabs.query({ url: CENTI });\n  if (!abas.length) return { erro: \"Abra a Centi (rioverde.centi.com.br) numa aba e faça o login.\" };\n  const estados = await Promise.all(abas.map((a) => estadoDaAba(a.id)));\n  const i = estados.findIndex((r) => r?.logado);\n  if (i >= 0) return { aba: abas[i], estado: estados[i] };\n  return { erro: \"Centi sem sessão: na aba da Centi já logada, clique em Pesquisar (ou abra qualquer tela).\" };\n}\n\n// ESCRITA: a confirmação na janela DA EXTENSÃO (a página do sistema não a desenha nem a aprova). Uma vez por execução e\n// protocolo; recusar, fechar a janela ou não responder em 2 min = não grava.\nasync function confirmarEscrita(a) {\n  const chave = `${a.execucaoId}|${a.id}`;\n  const { confirmadas = [] } = await chrome.storage.session.get(\"confirmadas\");\n  if (confirmadas.includes(chave)) return true;\n  const pedido = crypto.randomUUID();\n  const url = `${CONFIRMAR}?${new URLSearchParams({ pedido, execucao: String(a.execucaoId), id: a.id, numero: a.numero, ano: a.ano ?? \"\", descricao: a.descricao })}`;\n  const sim = await new Promise((ok) => {\n    let janela = null;\n    let feito = false;\n    const fim = (v) => {\n      if (feito) return;\n      feito = true;\n      clearTimeout(t);\n      chrome.runtime.onMessage.removeListener(ouvir);\n      chrome.windows.onRemoved.removeListener(fechou);\n      if (janela != null) chrome.windows.remove(janela).catch(() => {});\n      ok(v);\n    };\n    const ouvir = (m, sender) => {\n      if (sender.url?.startsWith(CONFIRMAR) && m?.tipo === \"confirmacao\" && m.pedido === pedido) fim(m.sim === true);\n    };\n    const fechou = (id) => {\n      if (id === janela) {\n        janela = null;\n        fim(false);\n      }\n    };\n    const t = setTimeout(() => fim(false), 120000);\n    chrome.runtime.onMessage.addListener(ouvir);\n    chrome.windows.onRemoved.addListener(fechou);\n    chrome.windows\n      .create({ url, type: \"popup\", width: 480, height: 460, focused: true })\n      .then((w) => {\n        janela = w.id;\n        if (feito) chrome.windows.remove(w.id).catch(() => {});\n      })\n      .catch(() => fim(false));\n  });\n  if (sim) await chrome.storage.session.set({ confirmadas: [...confirmadas, chave].slice(-50) });\n  return sim;\n}\n\nchrome.runtime.onInstalled.addListener(async () => {\n  for (const a of await chrome.tabs.query({ url: CENTI })) injetarCenti(a.id).catch(() => {});\n  for (const a of await chrome.tabs.query({ url: SISTEMA }))\n    chrome.scripting.executeScript({ target: { tabId: a.id }, files: [\"sistema-ponte.js\"] }).catch(() => {});\n});\n\nchrome.runtime.onMessage.addListener((msg, sender, responder) => {\n  const origem = sender.url ? new URL(sender.url).origin : \"\";\n  if (!ORIGENS.includes(origem) || !sender.url.includes(\"/painel/automacao\")) return false;\n  (async () => {\n    const { aba, erro, estado } = await abaCenti();\n    if (!aba) return { ok: false, erro };\n    // O estado vai inteiro: a entidade aberta e a OPERAÇÃO Emitir DFD que a extensão pegou da tela da Centi.\n    if (msg.acao === \"estado\") return { ok: true, logado: true, entidade: estado?.entidade ?? null, operacao: estado?.operacao ?? null };\n    if (![\"pedir\", \"protocolo\", \"anexar\"].includes(msg.acao)) return { ok: false, erro: \"Ação desconhecida.\" };\n    if (msg.acao === \"anexar\") {\n      // Só com a autorização já consumida no sistema pela ponte, para ESTE alvo (Id + nº + descrição do pedido).\n      const a = msg.autorizado;\n      const d = msg.dados ?? {};\n      if (!a || String(d.id) !== a.id || String(d.numero) !== a.numero || String(d.descricao ?? \"\") !== a.descricao)\n        return { ok: false, erro: \"Escrita sem a autorização do sistema para este protocolo.\" };\n      if (!(await confirmarEscrita(a))) return { ok: false, erro: \"Anexo não confirmado na janela da extensão — nada foi gravado.\" };\n    }\n    try {\n      return await chrome.tabs.sendMessage(aba.id, { alvo: \"centi\", acao: msg.acao, dados: msg.dados });\n    } catch {\n      return { ok: false, erro: \"A aba da Centi não respondeu — aperte F5 nela.\" };\n    }\n  })()\n    .catch((e) => ({ ok: false, erro: e?.message || \"Falha na extensão.\" }))\n    .then(responder);\n  return true;\n});\n",
  "centi-anexo.js": "// Peças PURAS do ANEXO de PDFs num protocolo da Centi (testadas: tests/automacao-centi.test.ts). Roda na página da Centi\n// ANTES do centi-main.js, que as usa: a ÚNICA gravação permitida é acrescentar UM documento novo ao protocolo que a própria\n// Centi acabou de devolver (load) — o resto do protocolo vai exatamente como veio (o que a tela da Centi faz no Salvar).\n// O nome leva a VERSÃO do protocolo: uma cópia antiga que ficou na aba (de uma versão anterior da extensão) nunca é\n// reaproveitada pela nova.\n(() => {\n  const NOME = \"__pcaCentiAnexo_p26\";\n  if (globalThis[NOME]) return;\n  // O protocolo abre por um destes módulos: 102907 (PO002 - Protocolo) ou 102908 (PO011 - Tela Protocolo). O protocolo\n  // que entrou na tramitação (\"Em análise\") a Centi só devolve pelo 102908 — o 102907 responde Entity nulo, sem mensagem.\n  const MODULO_PROTOCOLO = 102907;\n  const MODULOS_PROTOCOLO = [102907, 102908];\n  const MODULO_DOCUMENTO = 102932;\n  const MODULO_TIPO = 103868;\n  const TIPO = \"ORM.ObjectsJSON.Transports.ObjectDataJSON, ORM\";\n  // Listas que o load devolve nulas e a tela da Centi manda vazias no Salvar.\n  const LISTAS = [\"AtesteControleInterno\", \"LinksDownloads\", \"EtapasFluxo\"];\n  const MAX_PDF_B64 = 80 * 1024 * 1024;\n\n  const campos = (o) => (o && Array.isArray(o.Fields) ? o.Fields : []);\n  const valor = (o, k) => campos(o).find((f) => f.Key === k)?.Value;\n  const idDe = (v) => (v && typeof v === \"object\" ? valor(v, \"Id\") : v);\n  const texto = (v) => String(v ?? \"\").trim();\n  const mesmaDescricao = (a, b) => texto(a).replace(/\\s+/g, \" \").toUpperCase() === texto(b).replace(/\\s+/g, \" \").toUpperCase();\n  // Caractere de controle (quebra de linha, tab…) — não entra em descrição nem em nome de arquivo.\n  const temControle = (t) => [...t].some((c) => c.charCodeAt(0) < 32);\n  const dois = (n) => String(n).padStart(2, \"0\");\n  const dataCenti = (d) => `${dois(d.getDate())}/${dois(d.getMonth() + 1)}/${d.getFullYear()} ${dois(d.getHours())}:${dois(d.getMinutes())}:${dois(d.getSeconds())}`;\n\n  /** Valida o pedido do sistema (só dígitos nos códigos; o PDF em base64 começando por \"%PDF\"). Devolve o erro ou null. */\n  function validarPedido(d) {\n    if (!/^\\d{1,12}$/.test(String(d?.id ?? \"\"))) return \"Id do protocolo inválido.\";\n    if (!/^\\d{1,12}$/.test(String(d?.numero ?? \"\"))) return \"Nº do protocolo inválido.\";\n    if (d.ano != null && !/^\\d{4}$/.test(String(d.ano))) return \"Ano do protocolo inválido.\";\n    if (!/^\\d{1,9}$/.test(String(d?.tipo ?? \"\"))) return \"Tipo do documento inválido.\";\n    const desc = texto(d.descricao);\n    if (!desc || desc.length > 250 || temControle(desc)) return \"Descrição inválida.\";\n    const arq = texto(d.arquivo);\n    if (!/\\.pdf$/i.test(arq) || arq.length > 250 || temControle(arq) || /[/\\\\]/.test(arq)) return \"Nome do arquivo inválido.\";\n    const pdf = String(d.pdf ?? \"\");\n    if (!pdf.startsWith(\"JVBER\") || pdf.length > MAX_PDF_B64 || !/^[A-Za-z0-9+/]+=*$/.test(pdf)) return \"O arquivo não é um PDF.\";\n    return null;\n  }\n\n  /** O protocolo que a Centi devolveu no load: confere o Id e o NÚMERO (e o ano, quando informado) — nunca anexa noutro. */\n  function conferirProtocolo(retorno, d) {\n    const e = retorno?.Entity;\n    if (!e || !MODULOS_PROTOCOLO.includes(e.ModuleKey) || !Array.isArray(e.Fields)) {\n      // O que a Centi respondeu (a mensagem dela e a FORMA da resposta — nunca os dados), para o erro dizer o motivo.\n      const msg = mensagens(retorno?.Message);\n      const forma = retorno && typeof retorno === \"object\" ? Object.keys(retorno).slice(0, 8).join(\", \") : typeof retorno;\n      const mod = e && typeof e === \"object\" ? ` · módulo ${e.ModuleKey ?? \"?\"}` : \"\";\n      return { erro: `A Centi não devolveu o protocolo${msg ? `: ${msg}` : \" — confira o Id\"} (resposta: ${forma || \"vazia\"}${mod}).` };\n    }\n    if (texto(valor(e, \"Id\")) !== String(d.id)) return { erro: `A Centi não achou o protocolo de Id ${d.id}.` };\n    const numero = texto(valor(e, \"NrProtocolo\"));\n    const ano = texto(valor(e, \"AnoReferencia\"));\n    if (numero !== String(d.numero)) return { erro: `O Id ${d.id} é do protocolo ${numero || \"?\"}${ano ? `/${ano}` : \"\"}, não do ${d.numero}.` };\n    if (d.ano != null && ano !== String(d.ano)) return { erro: `O protocolo ${numero} é de ${ano || \"?\"}, não de ${d.ano}.` };\n    if (!Array.isArray(valor(e, \"Documentos\"))) return { erro: \"A Centi não devolveu os documentos do protocolo.\" };\n    return { entidade: e };\n  }\n\n  /** O resumo do protocolo (o \"Conferir\" da tela). */\n  function resumoProtocolo(e) {\n    const docs = valor(e, \"Documentos\") ?? [];\n    return {\n      id: texto(valor(e, \"Id\")),\n      numero: texto(valor(e, \"NrProtocolo\")),\n      ano: texto(valor(e, \"AnoReferencia\")),\n      assunto: texto(valor(valor(e, \"IdAssunto\"), \"Display\")),\n      interessado: texto(valor(valor(e, \"IdPessoa\"), \"Display\")),\n      descricao: texto(valor(e, \"Descricao\")),\n      documentos: docs.length,\n      descricoes: docs.map((x) => texto(valor(x, \"Descricao\"))),\n    };\n  }\n\n  /** O documento já anexado com a MESMA descrição (não anexa duas vezes). */\n  function jaAnexado(e, descricao) {\n    const doc = (valor(e, \"Documentos\") ?? []).find((x) => mesmaDescricao(valor(x, \"Descricao\"), descricao));\n    return doc ? { sequencial: texto(valor(doc, \"Sequencial\")), documento: texto(valor(doc, \"Id\")) } : null;\n  }\n\n  /** O TIPO do documento como a tela da Centi o manda: o registro do tipo (load do módulo de tipos, State 3) — só quando é\n   * mesmo o tipo pedido. */\n  function tipoDoLoad(retorno, tipo) {\n    const t = retorno?.Entity;\n    return t && t.ModuleKey === MODULO_TIPO && Array.isArray(t.Fields) && texto(valor(t, \"Id\")) === String(tipo) ? t : null;\n  }\n\n  /** O corpo do confirmsave/save: o protocolo do load SEM MUDANÇA + UM documento novo no fim (o formato da tela da Centi).\n   * O tipo: o registro do tipo (`tipoDoLoad` — o que a tela manda); sem ele, o objeto que a Centi já devolve num documento\n   * desse tipo; senão, a referência pelo Id. */\n  function montarSalvar(e, d, agora, guid, tipoCarregado = null) {\n    const docs = valor(e, \"Documentos\");\n    const igual = docs.find((x) => String(idDe(valor(x, \"IdPessoaDocumentoTipo\"))) === String(d.tipo));\n    const tipo =\n      tipoCarregado ??\n      (igual\n        ? valor(igual, \"IdPessoaDocumentoTipo\")\n        : { $type: TIPO, Type: 0, State: 10, ModuleKey: 0, Guid: null, Fields: [{ Key: \"Id\", Value: Number(d.tipo) }], DynamicAttributes: null });\n    const quando = dataCenti(agora);\n    const f = (Key, Value) => ({ Key, Value });\n    const novo = {\n      Type: 0,\n      State: 0,\n      // O módulo do documento = o de um documento que o protocolo já tem (o mesmo módulo de onde veio); sem nenhum, o padrão.\n      ModuleKey: docs.find((x) => Number.isInteger(x?.ModuleKey) && x.ModuleKey > 0)?.ModuleKey ?? MODULO_DOCUMENTO,\n      Guid: guid,\n      Fields: [\n        f(\"IdProtocolo\", \"0\"),\n        f(\"IdPessoaDocumentoTipo\", tipo),\n        f(\"Sequencial\", \"0\"),\n        f(\"Descricao\", texto(d.descricao)),\n        f(\"IdGed\", { Fields: [f(\"Id\", 0), f(\"FileName\", texto(d.arquivo)), f(\"Data\", String(d.pdf))] }),\n        f(\"IdGedOriginal\", \"0\"),\n        f(\"IdVinculo\", \"\"),\n        f(\"Documento\", \"\"),\n        f(\"Data\", quando),\n        f(\"IdReparticao\", \"0\"),\n        f(\"DescricaoCompletaReparticao\", \"\"),\n        f(\"TipoAndamento\", \"0\"),\n        f(\"IdUsuario\", \"0\"),\n        f(\"NomeUsuario\", \"\"),\n        f(\"IdProtocoloRegularidade\", \"0\"),\n        f(\"AvaliacaoRegularidade\", \"\"),\n        f(\"ObservacaoAvaliacao\", \"\"),\n        f(\"IdConceito\", \"0\"),\n        f(\"Status\", \"0\"),\n        f(\"DataRevogacao\", quando),\n        f(\"DocumentoExterno\", \"1\"),\n        f(\"ConfereOriginal\", \"0\"),\n        f(\"IdUsuarioConfereOriginal\", \"0\"),\n        f(\"NomeUsuarioConfereOriginal\", \"\"),\n        f(\"DataConfereOriginal\", quando),\n        f(\"ObservacaoConfereOriginal\", \"\"),\n        f(\"QuantidadePaginas\", \"0\"),\n        f(\"DocumentoSigiloso\", \"0\"),\n        f(\"IdUsuarioSigilo\", \"0\"),\n        f(\"Reassinar\", \"0\"),\n        f(\"Assinaturas\", []),\n        f(\"UsuariosSigilosos\", []),\n        f(\"Id\", \"0\"),\n        f(\"IdUsuarioCadastro\", \"0\"),\n        f(\"IdUsuarioAlteracao\", \"0\"),\n        f(\"DataCadastro\", \"\"),\n        f(\"LastUpdate\", \"\"),\n      ],\n      DynamicAttributes: [],\n    };\n    const Fields = e.Fields.map((c) =>\n      c.Key === \"Documentos\" ? { Key: c.Key, Value: [...docs, novo] } : LISTAS.includes(c.Key) && c.Value == null ? { Key: c.Key, Value: [] } : c,\n    );\n    return { Token: \"\", Object: { ...e, Fields } };\n  }\n\n  /** O corpo do CONFIRMSAVE = o OBJETO do protocolo DIRETO (a tela da Centi chama `confirmsave(initialValues)`); só o\n   * `save` leva o envelope `{Token, Object}`. O envelope no confirmsave chegava ao servidor como um objeto vazio (500). */\n  function corpoConfirmar(salvar) {\n    return salvar.Object;\n  }\n\n  /** O texto das mensagens da Centi (lista de textos ou de objetos). */\n  function mensagens(m) {\n    const lista = Array.isArray(m) ? m : m == null ? [] : [m];\n    return lista\n      .map((x) => (typeof x === \"string\" ? x : x && typeof x === \"object\" ? (x.Message ?? x.Text ?? x.Mensagem ?? x.Description ?? \"\") : \"\"))\n      .map(texto)\n      .filter(Boolean)\n      .join(\" · \");\n  }\n\n  /** A resposta do save: só vale com Success e o documento novo de volta com Id real. */\n  function conferirSalvo(r, d) {\n    if (r?.Success !== true) return { erro: `A Centi não gravou${mensagens(r?.Message) ? `: ${mensagens(r.Message)}` : \".\"}` };\n    const doc = (valor(r.Entity, \"Documentos\") ?? []).filter((x) => mesmaDescricao(valor(x, \"Descricao\"), d.descricao)).pop();\n    const id = texto(valor(doc, \"Id\"));\n    if (!doc || !id || id === \"0\") return { erro: \"A Centi respondeu, mas o documento não voltou no protocolo — confira na Centi.\" };\n    return { sequencial: texto(valor(doc, \"Sequencial\")), documento: id };\n  }\n\n  /** A dica do erro do salvar, pelos NOMES dos cabeçalhos (nunca os valores): os que a tela da Centi mandou no salvar e o\n   * anexo não mandou (os anti-robô \"x-ts…\" a extensão não reproduz); sem o salvar da tela aprendido, como ensiná-lo. */\n  function dicaCabecalhos(nomesTela, nomesEnviados, _protocoloAberto) {\n    if (!Array.isArray(nomesTela) || !nomesTela.length) return \"\";\n    const enviados = new Set((nomesEnviados ?? []).map((n) => String(n).toLowerCase()));\n    const fixos = /^(content-type|content-length|accept)$/i;\n    const faltam = nomesTela.map((n) => String(n).toLowerCase()).filter((n) => !fixos.test(n) && !enviados.has(n));\n    const robo = faltam.filter((n) => n.startsWith(\"x-ts\"));\n    const outros = faltam.filter((n) => !n.startsWith(\"x-ts\"));\n    if (outros.length) return `Cabeçalhos do salvar da Centi que faltaram: ${outros.join(\", \")}.`;\n    if (robo.length) return \"O salvar da Centi exige a verificação anti-robô da própria tela — anexe por ela.\";\n    return \"Os cabeçalhos são os mesmos da tela da Centi.\";\n  }\n\n  /** A trilha da tela da Centi antes do salvar dela (só \"MÉTODO caminho\"; números longos encurtados) e o endereço usado\n   * pelo anexo — o passo que a tela faz e o anexo não aparece aqui. Sem trilha: como aprendê-la. */\n  function dicaTrilha(trilha, usado) {\n    if (!Array.isArray(trilha) || !trilha.length) return \"\";\n    const curto = (t) => String(t).replace(/\\d{7,}/g, (n) => `${n.slice(0, 3)}…`).slice(0, 90);\n    return `Passos da tela antes de salvar: ${trilha.slice(-8).map(curto).join(\" › \")}. Anexo: ${curto(usado)}.`;\n  }\n\n  /** Os cabeçalhos de RASTREIO (trace-*, x-ai-trace…) vão NOVOS em cada pedido, como a tela os gera: um identificador\n   * repetido de um pedido antigo faz o salvar da Centi falhar (\"Erro inesperado\"). No valor, cada GUID vira um GUID novo,\n   * cada carimbo de tempo em ms vira o de agora e cada sequência hexadecimal/alfanumérica longa vira outra do mesmo\n   * tamanho. Os demais cabeçalhos (sessão, entidade, mês…) ficam como estão. */\n  const RASTREIO = /^(x-ai-trace|x-trace|trace-|x-request-id|request-id|x-correlation-id|correlation-id)/i;\n  function renovarRastreio(cab, guid, agora, aleatorio) {\n    const novoDe = (amostra) => {\n      const hex = /^[0-9a-f]+$/i.test(amostra);\n      const alfabeto = hex ? \"0123456789abcdef\" : \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789\";\n      let r = \"\";\n      for (let i = 0; i < amostra.length; i++) r += alfabeto[Math.floor(aleatorio() * alfabeto.length)];\n      return amostra === amostra.toUpperCase() && hex ? r.toUpperCase() : r;\n    };\n    const r = {};\n    for (const [k, v] of Object.entries(cab ?? {})) {\n      if (!RASTREIO.test(k)) {\n        r[k] = v;\n        continue;\n      }\n      r[k] = String(v ?? \"\")\n        .replace(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi, () => guid())\n        .replace(/(?<![0-9a-z])1\\d{12}(?![0-9a-z])/gi, () => String(agora))\n        .replace(/(?<![0-9a-z-])[0-9a-z]{16,}(?![0-9a-z-])/gi, (m) => novoDe(m));\n    }\n    return r;\n  }\n\n  /** Os cabeçalhos com o TOKEN que a Centi devolveu na resposta (ela troca a cada resposta e a tela usa o novo):\n   * token, Authorization \"Bearer <token>\" e refreshtoken — no nome que já existe (sem caixa), senão acrescentados. Sem\n   * token novo, os mesmos cabeçalhos. */\n  function comTokenNovo(cab, token, refresh) {\n    if (!token && !refresh) return cab;\n    // Só ATUALIZA o cabeçalho que a tela da Centi já manda (pelo nome, sem caixa) — NUNCA acrescenta um: a tela não manda\n    // \"token\"/\"Authorization\" no operation (só Refreshtoken + Company + Month), e acrescentá-los fazia a Centi responder\n    // \"Usuário sem permissão!\" na emissão do DFD (1.3.8 a 1.3.17).\n    const novo = { ...cab };\n    let mudou = false;\n    const por = (re, valor) => {\n      const k = Object.keys(novo).find((n) => re.test(n));\n      if (k && novo[k] !== valor) {\n        novo[k] = valor;\n        mudou = true;\n      }\n    };\n    if (token) {\n      por(/^token$/i, token);\n      por(/^authorization$/i, `Bearer ${token}`);\n    }\n    if (refresh) por(/^refreshtoken$/i, refresh);\n    return mudou ? novo : cab;\n  }\n\n  /** A OPERAÇÃO \"Emitir DFD\" que a própria tela da Centi mandou (o corpo do operation, como texto ou objeto): só o que a\n   * identifica — ModuleKey, Guid e o modelo de assinatura (IdPlanejamentoAssinaturaDFD). Outro operation → null. Nunca\n   * guarda o planejamento nem os demais valores. */\n  function operacaoDoCorpo(corpo) {\n    let c = corpo;\n    if (typeof c === \"string\") {\n      try {\n        c = JSON.parse(c);\n      } catch {\n        return null;\n      }\n    }\n    if (!c || typeof c !== \"object\" || !Number.isInteger(c.ModuleKey) || c.ModuleKey <= 0 || !Array.isArray(c.Params)) return null;\n    const guid = String(c.Guid ?? \"\").toLowerCase();\n    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(guid)) return null;\n    const p = (k) => c.Params.find((x) => x && x.Key === k);\n    if (!p(\"IdComprasPlanejamento\") || String(p(\"DFD\")?.Value ?? \"\") !== \"1\") return null;\n    const assinatura = String(p(\"IdPlanejamentoAssinaturaDFD\")?.Value ?? \"\").replace(/\\D/g, \"\");\n    return { moduleKey: c.ModuleKey, guid, assinatura };\n  }\n\n  globalThis[NOME] = Object.freeze({\n    comTokenNovo,\n    operacaoDoCorpo,\n    renovarRastreio, validarPedido, conferirProtocolo, resumoProtocolo, jaAnexado, montarSalvar, corpoConfirmar, mensagens, conferirSalvo, tipoDoLoad, dicaCabecalhos, dicaTrilha, MODULO_PROTOCOLO, MODULOS_PROTOCOLO, MODULO_TIPO });\n})();\n",
  "centi-main.js": "// Roda DENTRO da página da Centi (extensão \"fina\"): guarda os cabeçalhos que a própria Centi usa na API (sessão da aba,\n// entidade, mês) e executa, com eles, o pedido que a aba Automação manda. A LÓGICA (montar o Emitir DFD, ler a resposta,\n// achar o PDF) mora no sistema — atualiza sem reinstalar a extensão. Aqui ficam só as TRAVAS: só a Centi, só leitura\n// (GET) da API e, para POST, só a operação \"Emitir DFD\" com não vincular/não assinar/não enviar forçados. A ÚNICA gravação\n// é o ANEXO (\"anexar\"): abre o protocolo pelo load da própria Centi, confere Id + número, acrescenta UM documento novo\n// (centi-anexo.js) e salva — o sistema nunca manda o objeto do protocolo.\n(() => {\n  const PROTOCOLO = 26;\n  const MARCA = `__pcaCentiMain_p${PROTOCOLO}`;\n  if (window[MARCA]) return;\n  window[MARCA] = true;\n  // Versão nova da chave: a sessão guardada pelas 1.3.8–1.3.17 trazia cabeçalhos acrescentados (token/Authorization).\n  const SESSAO = \"__pcaCentiSessao_v2\";\n  let base = \"\";\n  let cabecalhos = null;\n  // Os cabeçalhos que a PRÓPRIA tela da Centi usou no salvar (confirmsave/save) e ao abrir um protocolo (load do módulo\n  // 102907): o salvar do anexo vai com eles — o último pedido da aba costuma ser de OUTRA tela (a pesquisa do DFD), com o\n  // contexto dela. `nomesSalvar` = os NOMES (só os nomes) que a tela mandou no salvar, para o erro dizer o que faltou.\n  let doSalvar = null;\n  let doProtocolo = null;\n  let nomesSalvar = null;\n  let tipoSalvar = null;\n  // O endereço EXATO (caminho + parâmetros) que a tela usou no confirmsave/save e a TRILHA dos pedidos dela antes de\n  // salvar (só \"MÉTODO caminho\" — a sessão vai nos cabeçalhos, nunca na URL): o anexo usa o mesmo endereço e o erro mostra\n  // a trilha (o passo que a tela faz e a extensão não).\n  let urlsSalvar = {};\n  // COMO a tela enviou o salvar: \"xhr\" | \"fetch\" — o anexo usa o mesmo meio (a proteção anti-robô da página assina os\n  // pedidos dela pelo meio e pelo endereço COMO a tela os escreve; por isso o endereço guardado é o BRUTO).\n  let viaSalvar = null;\n  let trilha = [];\n  let trilhaSalvar = null;\n  // A OPERAÇÃO \"Emitir DFD\" que a tela da Centi usou por último nesta aba (ModuleKey, Guid, modelo de assinatura): a\n  // extensão a pega SOZINHA quando alguém clica em Processar — o sistema se ajusta quando a Centi a muda.\n  let operacaoTela = null;\n  // As operações que a PRÓPRIA extensão está enviando pelo cliente da Centi — não são da tela, não se aprende delas.\n  const proprias = new Set();\n  // A sessão da Centi é POR ABA (sessionStorage): a última capturada vale também depois de um F5 ou de uma atualização.\n  try {\n    const salvo = JSON.parse(sessionStorage.getItem(SESSAO) || \"null\");\n    if (salvo?.base && salvo?.cabecalhos) ({ base, cabecalhos } = salvo);\n    if (salvo?.doSalvar) ({ doSalvar, nomesSalvar, tipoSalvar } = salvo);\n    if (salvo?.urlsSalvar) ({ urlsSalvar, trilhaSalvar, viaSalvar } = salvo);\n    if (salvo?.doProtocolo) doProtocolo = salvo.doProtocolo;\n    if (salvo?.operacaoTela) operacaoTela = salvo.operacaoTela;\n  } catch {}\n  const IGNORAR = /^(content-type|accept|content-length|x-ts)/i;\n  const SESSAO_CAB = /^(authorization|token|refreshtoken|company)$/i;\n\n  function guardar(url, hs, metodo, via) {\n    const u = String(url);\n    const i = u.indexOf(\"/restauth/\");\n    if (i < 0) return;\n    const limpos = {};\n    for (const [k, v] of Object.entries(hs)) if (!IGNORAR.test(k)) limpos[k] = v;\n    // A sessão da Centi vai num destes cabeçalhos (no \"operation\" capturado: Refreshtoken + Company + Month).\n    if (!Object.keys(limpos).some((k) => SESSAO_CAB.test(k))) return;\n    base = new URL(u.slice(0, i), location.href).href;\n    cabecalhos = limpos;\n    const caminho = u.slice(i);\n    const passo = `${String(metodo || \"GET\").toUpperCase()} ${caminho.slice(\"/restauth/\".length).slice(0, 160)}`;\n    trilha = [...trilha, passo].slice(-12);\n    const salvar = /^POST$/i.test(metodo || \"\") && caminho.match(/^\\/restauth\\/(confirmsave|save)(\\?|$)/i);\n    if (salvar) {\n      doSalvar = limpos;\n      nomesSalvar = Object.keys(hs).map((k) => k.toLowerCase()).sort();\n      tipoSalvar = Object.entries(hs).find(([k]) => /^content-type$/i.test(k))?.[1] ?? null;\n      urlsSalvar = { ...urlsSalvar, [salvar[1].toLowerCase()]: u };\n      viaSalvar = via;\n      if (salvar[1].toLowerCase() === \"confirmsave\") trilhaSalvar = trilha.slice(0, -1);\n    } else if (/[?&]entity=102907(&|$)/.test(caminho)) doProtocolo = limpos;\n    try {\n      sessionStorage.setItem(SESSAO, JSON.stringify({ base, cabecalhos, doSalvar, nomesSalvar, tipoSalvar, doProtocolo, urlsSalvar, trilhaSalvar, viaSalvar, operacaoTela }));\n    } catch {}\n  }\n\n  // Os cabeçalhos do salvar: os da tela (salvar › protocolo › último pedido) com a SESSÃO sempre a mais recente.\n  function cabecalhosDoSalvar() {\n    const contexto = doSalvar ?? doProtocolo ?? cabecalhos;\n    const sessao = Object.fromEntries(Object.entries(cabecalhos).filter(([k]) => SESSAO_CAB.test(k) || /^month$/i.test(k)));\n    const r = {};\n    for (const [k, v] of Object.entries(contexto)) if (!Object.keys(sessao).some((s) => s.toLowerCase() === k.toLowerCase())) r[k] = v;\n    return { ...r, ...sessao };\n  }\n\n  // O TOKEN da Centi TROCA a cada resposta: o servidor devolve \"token\" e \"refreshtoken\" novos e a tela passa a usá-los\n  // (Authorization = \"Bearer <token>\"). A extensão acompanha — lê o token novo de TODA resposta (da tela e dela) e sempre\n  // manda o mais recente; com o antigo, o salvar dava \"Erro inesperado\" (500) e as renovações forçadas, 429.\n  function trocarToken(ler) {\n    const A = globalThis[`__pcaCentiAnexo_p${PROTOCOLO}`];\n    if (!cabecalhos || !A) return;\n    const novo = A.comTokenNovo(cabecalhos, ler(\"token\"), ler(\"refreshtoken\"));\n    if (novo === cabecalhos) return;\n    cabecalhos = novo;\n    try {\n      sessionStorage.setItem(SESSAO, JSON.stringify({ base, cabecalhos, doSalvar, nomesSalvar, tipoSalvar, doProtocolo, urlsSalvar, trilhaSalvar, viaSalvar, operacaoTela }));\n    } catch {}\n  }\n  const tokenDoXhr = (x) => (n) => {\n    try {\n      return x.getResponseHeader(n) || null;\n    } catch {\n      return null;\n    }\n  };\n\n  // A tela da Centi mandou um \"Emitir DFD\" (o operation do Processar): guarda a operação dela.\n  function aprenderOperacao(url, metodo, corpo) {\n    try {\n      if (!/^POST$/i.test(metodo || \"\") || !/\\/restauth\\/operation(\\?|$)/.test(String(url))) return;\n      const pecas = globalThis[`__pcaCentiAnexo_p${PROTOCOLO}`];\n      const op = pecas?.operacaoDoCorpo(corpo);\n      if (!op || proprias.has(`${op.moduleKey}|${op.guid}`)) return;\n      operacaoTela = { ...op, em: new Date().toISOString() };\n      sessionStorage.setItem(SESSAO, JSON.stringify({ base, cabecalhos, doSalvar, nomesSalvar, tipoSalvar, doProtocolo, urlsSalvar, trilhaSalvar, viaSalvar, operacaoTela }));\n    } catch {}\n  }\n\n  const abrir = XMLHttpRequest.prototype.open;\n  const definir = XMLHttpRequest.prototype.setRequestHeader;\n  const enviar = XMLHttpRequest.prototype.send;\n  XMLHttpRequest.prototype.open = function (m, url, ...r) {\n    this.__pcaUrl = url;\n    this.__pcaMetodo = m;\n    this.__pcaHs = {};\n    return abrir.call(this, m, url, ...r);\n  };\n  XMLHttpRequest.prototype.setRequestHeader = function (k, v) {\n    if (this.__pcaHs) this.__pcaHs[k] = v;\n    return definir.call(this, k, v);\n  };\n  XMLHttpRequest.prototype.send = function (...r) {\n    if (this.__pcaUrl && !this.__pcaInterno) {\n      guardar(this.__pcaUrl, this.__pcaHs || {}, this.__pcaMetodo, \"xhr\");\n      aprenderOperacao(this.__pcaUrl, this.__pcaMetodo, r[0]);\n    }\n    if (this.__pcaUrl && String(this.__pcaUrl).includes(\"/restauth/\")) this.addEventListener(\"load\", () => trocarToken(tokenDoXhr(this)));\n    return enviar.apply(this, r);\n  };\n  const buscar = window.fetch;\n  window.fetch = function (rec, init, ...resto) {\n    const comToken = (p) =>\n      p.then((r) => {\n        try {\n          if (String(r.url || \"\").includes(\"/restauth/\")) trocarToken((n) => r.headers.get(n));\n        } catch {}\n        return r;\n      });\n    if (init?.__pcaInterno) return comToken(buscar.call(this, rec, init, ...resto));\n    try {\n      const url = typeof rec === \"string\" ? rec : rec?.url;\n      const hs = new Headers(init?.headers || (typeof rec === \"object\" ? rec.headers : undefined));\n      const metodo = init?.method || (typeof rec === \"object\" ? rec.method : \"GET\");\n      guardar(url, Object.fromEntries(hs.entries()), metodo, \"fetch\");\n      aprenderOperacao(url, metodo, init?.body);\n    } catch {}\n    return comToken(buscar.call(this, rec, init, ...resto));\n  };\n\n  const TRAVAS = { AnexarAoProtocolo: \"0\", AssinarDocumento: \"0\", Sign: \"0\", SendMail: \"0\", StorageReport: \"0\", Background: \"0\" };\n  const GUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;\n  // Os endereços do ARQUIVO gerado pelo Emitir DFD (os únicos que a leitura alcança).\n  const ARQUIVO = /\\/(restauth|rest)\\/(getbinlink|getbin|getfile)\\//i;\n\n  function emBase64(bytes) {\n    let s = \"\";\n    for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));\n    return btoa(s);\n  }\n\n  // O destino tem de ser a API da Centi desta aba (mesma origem, dentro de /restauth/ ou /rest/).\n  function destino(caminho) {\n    const u = new URL(caminho, `${base}/`);\n    if (u.origin !== location.origin || !/\\/(restauth|rest)\\//.test(u.pathname)) return null;\n    return u.href;\n  }\n\n  // A ENTIDADE aberta na aba (o cabeçalho Company que a própria Centi manda — muda quando se troca a entidade lá).\n  const nomeEntidade = () => (cabecalhos ? Object.keys(cabecalhos).find((k) => /^company$/i.test(k)) : undefined);\n  const entidadeAtual = () => {\n    const k = nomeEntidade();\n    return k ? String(cabecalhos[k]) : null;\n  };\n\n  function executar(metodo, url, corpo, entidade, comoTexto = false, cab = cabecalhos, tipo = \"application/json\", bruto = url, rastreioNovo = true) {\n    return new Promise((ok, falha) => {\n      const x = new XMLHttpRequest();\n      x.__pcaInterno = true;\n      x.open(metodo, bruto);\n      x.responseType = comoTexto ? \"text\" : \"arraybuffer\";\n      const k = nomeEntidade();\n      // O rastreio vai NOVO em cada pedido (como a tela gera) — nunca o identificador de um pedido antigo.\n      const hs = A && rastreioNovo ? A.renovarRastreio(cab, () => crypto.randomUUID(), Date.now(), Math.random) : cab;\n      for (const [n, v] of Object.entries(hs)) x.setRequestHeader(n, entidade && n === k ? entidade : v);\n      if (entidade && !k) x.setRequestHeader(\"Company\", entidade);\n      if (corpo) x.setRequestHeader(\"Content-Type\", tipo);\n      x.setRequestHeader(\"Accept\", \"application/json, text/plain, */*\");\n      x.onload = () => {\n        // O token novo desta resposta vale JÁ para o próximo pedido (antes de a sequência continuar).\n        trocarToken(tokenDoXhr(x));\n        return ok(\n          comoTexto\n            ? { status: x.status, texto: String(x.response ?? \"\"), enviados: Object.keys(x.__pcaHs || {}) }\n            : { ok: true, status: x.status, tipo: x.getResponseHeader(\"content-type\") || \"\", b64: emBase64(new Uint8Array(x.response || new ArrayBuffer(0))) },\n        );\n      };\n      x.onerror = () => falha(new Error(\"Sem resposta da Centi (rede).\"));\n      x.timeout = comoTexto ? 280000 : 120000;\n      x.ontimeout = () => falha(new Error(\"A Centi demorou demais para responder.\"));\n      x.send(corpo ? JSON.stringify(corpo) : null);\n    });\n  }\n\n  // O salvar pelo FETCH da página (o mesmo meio da tela): passa pelos envoltórios que a página pôs no fetch.\n  async function executarFetch(metodo, bruto, corpo, cab, tipo) {\n    const hs = { ...(A ? A.renovarRastreio(cab, () => crypto.randomUUID(), Date.now(), Math.random) : cab), Accept: \"application/json, text/plain, */*\" };\n    if (corpo) hs[\"Content-Type\"] = tipo;\n    const r = await window.fetch(bruto, { method: metodo, headers: hs, body: corpo ? JSON.stringify(corpo) : undefined, credentials: \"include\", __pcaInterno: true });\n    return { status: r.status, texto: await r.text(), enviados: Object.keys(hs) };\n  }\n\n  async function pedir(d) {\n    if (!cabecalhos) return { ok: false, erro: \"Centi sem sessão: na aba da Centi já logada, clique em Pesquisar.\" };\n    const url = destino(String(d?.caminho || \"\"));\n    if (!url) return { ok: false, erro: \"Destino fora da API da Centi.\" };\n    // A entidade (órgão) do DFD, quando difere da aberta na aba: só um código simples, só neste pedido.\n    const ent = d.entidade == null || d.entidade === \"\" ? null : String(d.entidade);\n    if (ent !== null && !/^[\\w.-]{1,40}$/.test(ent)) return { ok: false, erro: \"Entidade inválida.\" };\n    // A EMISSÃO vai com os cabeçalhos da aba EXATAMENTE como a tela os mandou (como na 1.2.0, quando funcionava) — sem\n    // renovar o rastreio (que é só do salvar do anexo).\n    // TRAVA: a leitura (GET) só baixa o ARQUIVO gerado (getbinlink/getbin/getfile) — nenhum outro endereço da API.\n    if (d.metodo === \"GET\") {\n      if (!ARQUIVO.test(new URL(url).pathname)) return { ok: false, erro: \"Só o download do PDF gerado é permitido.\" };\n      return (await binarioPelaCenti(\"GET\", url, null, ent)) ?? executar(\"GET\", url, null, ent, false, cabecalhos, \"application/json\", url, false);\n    }\n    if (d.metodo !== \"POST\" || !/\\/restauth\\/operation$/.test(new URL(url).pathname)) return { ok: false, erro: \"Só a operação Emitir DFD é permitida.\" };\n    const c = d.corpo;\n    if (!c || !GUID.test(String(c.Guid)) || !Number.isInteger(c.ModuleKey) || !Array.isArray(c.Params)) return { ok: false, erro: \"Pedido inválido.\" };\n    // TRAVA: só a operação com a FORMA do Emitir DFD (IdComprasPlanejamento + DFD=1) — nenhuma outra operação da Centi.\n    if (!A?.operacaoDoCorpo(c)) return { ok: false, erro: \"Só a operação Emitir DFD é permitida.\" };\n    const params = c.Params.map((p) => ({ Key: String(p.Key), Value: p.Key in TRAVAS ? TRAVAS[p.Key] : String(p.Value ?? \"\") }));\n    for (const [Key, Value] of Object.entries(TRAVAS)) if (!params.some((p) => p.Key === Key)) params.push({ Key, Value });\n    const corpo = { ModuleKey: c.ModuleKey, Guid: c.Guid, Params: params };\n    return (await binarioPelaCenti(\"POST\", url, corpo, ent)) ?? executar(\"POST\", url, corpo, ent, false, cabecalhos, \"application/json\", url, false);\n  }\n\n  // A EMISSÃO e o download saem pelo CLIENTE HTTP DA PRÓPRIA CENTI — o MESMO caminho do anexo, que funciona: os\n  // cabeçalhos, o token e o contexto são os que a tela usa naquele instante (não os do último pedido capturado na aba).\n  // Só para a API /restauth/ (a base do cliente); sem o cliente ou sem resposta, null → o envio da extensão.\n  async function binarioPelaCenti(metodo, url, corpo, ent) {\n    const cli = acharClienteCenti();\n    if (!cli) return null;\n    const u = new URL(url);\n    const i = u.pathname.indexOf(\"/restauth/\");\n    if (i < 0) return null;\n    const rel = `${u.pathname.slice(i + \"/restauth\".length)}${u.search}`;\n    const headers = {};\n    if (ent !== null) headers[nomeEntidade() || \"Company\"] = ent;\n    const resposta = (r) => {\n      tokenNosClientes(cli, r.headers);\n      const dados = r.data;\n      // ArrayBuffer (ou visão dele) por FORMA, não por instanceof — vale também se vier de outro \"realm\".\n      const binario = dados && typeof dados === \"object\" && typeof dados.byteLength === \"number\";\n      const bytes = binario\n        ? ArrayBuffer.isView(dados)\n          ? new Uint8Array(dados.buffer, dados.byteOffset, dados.byteLength)\n          : new Uint8Array(dados)\n        : new TextEncoder().encode(typeof dados === \"string\" ? dados : JSON.stringify(dados ?? null));\n      const tipo = (typeof r.headers?.get === \"function\" ? r.headers.get(\"content-type\") : r.headers?.[\"content-type\"]) || \"\";\n      return { ok: true, status: r.status, tipo: String(tipo), b64: emBase64(bytes) };\n    };\n    const propria = corpo ? `${corpo.ModuleKey}|${String(corpo.Guid).toLowerCase()}` : null;\n    if (propria) proprias.add(propria);\n    try {\n      return resposta(await cli.principal.request({ method: metodo, url: rel, data: corpo ?? undefined, headers, responseType: \"arraybuffer\" }));\n    } catch (e) {\n      return e?.response ? resposta(e.response) : null;\n    } finally {\n      if (propria) proprias.delete(propria);\n    }\n  }\n\n  // JSON da API da Centi (load/confirmsave/save): HTTP de erro ou corpo que não é JSON → o motivo, nunca segue às cegas.\n  const A = globalThis[`__pcaCentiAnexo_p${PROTOCOLO}`];\n  // `passo` entra no erro (load/confirmsave/save): diz ONDE a Centi recusou.\n  async function api(metodo, caminho, corpo, passo, salvar = false, bruto = caminho) {\n    // O endereço bruto da tela é relativo à PÁGINA (como o navegador o resolve no open/fetch).\n    const url = destino(bruto === caminho ? caminho : new URL(bruto, location.href).href);\n    if (!url) throw new Error(\"Destino fora da API da Centi.\");\n    const cab = salvar ? cabecalhosDoSalvar() : cabecalhos;\n    const tipo = (salvar && tipoSalvar) || \"application/json\";\n    // O endereço vai ao open/fetch ESCRITO como a tela o escreveu (relativo ou completo).\n    const r =\n      salvar && viaSalvar === \"fetch\"\n        ? await executarFetch(metodo, bruto, corpo, cab, tipo)\n        : await executar(metodo, url, corpo, null, true, cab, tipo, salvar ? bruto : url);\n    let j = null;\n    try {\n      j = JSON.parse(r.texto);\n    } catch {}\n    if (r.status >= 400 || !j) {\n      const msg = `A Centi recusou o ${passo} (${r.status})${j ? `: ${A.mensagens(j.Message) || \"sem mensagem\"}` : \".\"}`;\n      throw new Error(\n        salvar\n          ? [msg, A.dicaCabecalhos(nomesSalvar, r.enviados ?? Object.keys(cab), !!doProtocolo), A.dicaTrilha(trilhaSalvar, `${viaSalvar || \"xhr\"} ${caminho}`)].filter(Boolean).join(\" \")\n          : msg,\n      );\n    }\n    return j;\n  }\n\n  // O CLIENTE HTTP DA PRÓPRIA CENTI (a instância do axios em \".../restauth\" que a tela usa no load/confirmsave/save):\n  // achado pelo FORMATO entre os módulos do webpack da página (nunca pelo número do módulo, que muda a cada publicação da\n  // Centi). Por ele o pedido sai EXATAMENTE como o da tela — token, cabeçalhos, proteção anti-robô — e, como a tela faz\n  // (a função \"E\" do código dela), o token novo de cada resposta passa a valer em todos os clientes dela.\n  let clienteCenti = null;\n  let motivoSemCliente = \"\";\n  function acharClienteCenti() {\n    if (clienteCenti) return clienteCenti;\n    try {\n      const nome = Object.keys(window).find((k) => k.startsWith(\"webpackJsonp\") && Array.isArray(window[k]));\n      if (!nome) {\n        motivoSemCliente = \"a página não expõe os módulos\";\n        return null;\n      }\n      let req = null;\n      const id = `__pcaCenti${Date.now()}${Math.random().toString(36).slice(2)}`;\n      window[nome].push([[id], { [id]: (_m, _e, r) => (req = r) }, [[id]]]);\n      if (!req?.c) {\n        motivoSemCliente = \"sem acesso aos módulos da página\";\n        return null;\n      }\n      // Cada módulo e cada exportação lidos com proteção: uma exportação ainda não pronta (lança ao ler) não pode\n      // interromper a busca inteira.\n      const instancias = new Set();\n      const lojas = new Set();\n      const olhar = (v) => {\n        if (typeof v === \"function\" && v.defaults && v.interceptors && typeof v.post === \"function\" && typeof v.get === \"function\") instancias.add(v);\n        else if (v && typeof v === \"object\" && typeof v.getState === \"function\" && typeof v.dispatch === \"function\") lojas.add(v);\n      };\n      for (const chave of Object.keys(req.c)) {\n        let ex;\n        try {\n          ex = req.c[chave]?.exports;\n        } catch {\n          continue;\n        }\n        if (!ex || (typeof ex !== \"object\" && typeof ex !== \"function\")) continue;\n        try {\n          olhar(ex);\n        } catch {}\n        let nomes = [];\n        try {\n          nomes = Object.keys(ex);\n        } catch {}\n        for (const n of nomes) {\n          try {\n            olhar(ex[n]);\n          } catch {}\n        }\n      }\n      const base = (v) => {\n        try {\n          return String(v.defaults.baseURL || \"\");\n        } catch {\n          return \"\";\n        }\n      };\n      const todas = [...instancias];\n      const daApi = todas.filter((v) => /\\/restauth\\/?$/.test(base(v)));\n      // A da tela (load/confirmsave/save) é a sem tempo-limite próprio; as demais recebem o token junto.\n      const principal = daApi.find((v) => !v.defaults.timeout) ?? daApi[0] ?? null;\n      if (!principal) {\n        motivoSemCliente = `nenhum cliente da API entre ${todas.length} encontrados`;\n        return null;\n      }\n      // O ESTADO da tela (redux): a lista das entidades — o nome da entidade de um módulo, que o LoadObjectReference pede.\n      const loja =\n        [...lojas].find((l) => {\n          try {\n            return Array.isArray(l.getState()?.Entities);\n          } catch {\n            return false;\n          }\n        }) ?? null;\n      clienteCenti = { principal, loja, todas: todas.filter((v) => /\\/(restauth|vicenti)\\/?$/.test(base(v))) };\n    } catch (e) {\n      motivoSemCliente = e?.message || \"falha ao procurar\";\n    }\n    return clienteCenti;\n  }\n  function tokenNosClientes(_cli, h) {\n    const ler = (n) => (h && (typeof h.get === \"function\" ? h.get(n) : h[n])) || null;\n    const token = ler(\"token\");\n    const refresh = ler(\"refreshtoken\");\n    // NUNCA escreve nos clientes da própria Centi (antes punha token/Authorization nos padrões deles e mudava a sessão da\n    // página); a tela cuida do token dela. Só a cópia da extensão acompanha.\n    if (!token && !refresh) return;\n    trocarToken(ler);\n  }\n  /** Um pedido pelo cliente da Centi: { status, j } (j = o JSON da resposta), ou null sem o cliente. */\n  async function pelaCenti(metodo, caminho, corpo) {\n    const cli = acharClienteCenti();\n    if (!cli) return null;\n    const rel = `/${String(caminho).replace(/^\\/?restauth\\//, \"\")}`;\n    try {\n      const r = metodo === \"GET\" ? await cli.principal.get(rel) : await cli.principal.post(rel, corpo);\n      tokenNosClientes(cli, r.headers);\n      return { status: r.status, j: r.data };\n    } catch (e) {\n      const r = e?.response;\n      if (!r) throw new Error(`Sem resposta da Centi (${e?.message || \"rede\"}).`);\n      tokenNosClientes(cli, r.headers);\n      return { status: r.status, j: r.data };\n    }\n  }\n  /** A API da Centi: pelo cliente da própria tela; sem ele, pelo envio da extensão. */\n  async function apiCenti(metodo, caminho, corpo, passo, salvar = false, bruto = caminho) {\n    const r = await pelaCenti(metodo, caminho, corpo);\n    if (!r) {\n      try {\n        return await api(metodo, caminho, corpo, passo, salvar, bruto);\n      } catch (e) {\n        throw new Error(`${e?.message || \"Falha na Centi.\"} (cliente da Centi não encontrado: ${motivoSemCliente || \"?\"})`);\n      }\n    }\n    const j = r.j && typeof r.j === \"object\" ? r.j : null;\n    if (r.status >= 400 || !j) throw new Error(`A Centi recusou o ${passo} (${r.status})${j ? `: ${A.mensagens(j.Message) || \"sem mensagem\"}` : \".\"} (pelo cliente da Centi)`);\n    return j;\n  }\n\n  /** O nome da entidade de um módulo (o que a tela manda no LoadObjectReference), pelo estado da tela; sem ele, null. */\n  function entidadeDoModulo(cli, modulo) {\n    try {\n      const lista = cli?.loja?.getState()?.Entities ?? [];\n      const e = lista.find((x) => String(x?.Key) === String(modulo));\n      return e?.Value?.Name || null;\n    } catch {\n      return null;\n    }\n  }\n  /** O TIPO do documento como a TELA o obtém ao escolhê-lo: o LoadObjectReference (registra a referência no servidor da\n   * Centi — o salvar a procura), logo depois de abrir o protocolo. Sem como fazer igual, null. */\n  async function tipoPorReferencia(d) {\n    const cli = acharClienteCenti();\n    const entidade = entidadeDoModulo(cli, A.MODULO_TIPO);\n    if (!cli || !entidade) return null;\n    const r = await pelaCenti(\"POST\", \"restauth/LoadObjectReference\", { Items: [{ DisplayOnReference: [], Entity: entidade, Id: Number(d.tipo) }] });\n    const lista = Array.isArray(r?.j) ? r.j : [];\n    return A.tipoDoLoad({ Entity: lista.find((o) => o?.ModuleKey === A.MODULO_TIPO) ?? lista[0] }, d.tipo);\n  }\n\n  // Abre o protocolo pelo módulo que a Centi aceitar (102907, senão 102908 — o da Tela Protocolo): só segue ao próximo\n  // quando a Centi não devolveu o protocolo; Id/número que não conferem param na hora.\n  async function abrirProtocolo(d) {\n    let ultimo = null;\n    for (const modulo of A.MODULOS_PROTOCOLO) {\n      const r = await apiCenti(\"GET\", `restauth/load?entity=${modulo}&key=${d.id}`, null, \"load do protocolo\");\n      const c = A.conferirProtocolo(r, d);\n      if (!c.erro) return c.entidade;\n      ultimo = c.erro;\n      if (r?.Entity) break;\n    }\n    throw new Error(ultimo);\n  }\n\n  // Só LEITURA: o resumo do protocolo (o \"Conferir\" da tela).\n  async function protocolo(d) {\n    if (!A) return { ok: false, erro: \"Extensão incompleta na aba da Centi — aperte F5 nela.\" };\n    if (!cabecalhos) return { ok: false, erro: \"Centi sem sessão: na aba da Centi já logada, clique em Pesquisar.\" };\n    const erro = A.validarPedido({ ...d, tipo: \"1\", descricao: \"x\", arquivo: \"x.pdf\", pdf: \"JVBER\" });\n    if (erro) return { ok: false, erro };\n    return { ok: true, protocolo: A.resumoProtocolo(await abrirProtocolo(d)) };\n  }\n\n  // A ÚNICA gravação: UM documento novo no protocolo conferido. Já anexado (mesma descrição) → não anexa de novo. A Centi\n  // pedindo confirmação (confirmsave) → devolve a pergunta; o save só com o \"sim\" do ADM (`aceitar`), nunca sozinha.\n  async function anexar(d) {\n    if (!A) return { ok: false, erro: \"Extensão incompleta na aba da Centi — aperte F5 nela.\" };\n    if (!cabecalhos) return { ok: false, erro: \"Centi sem sessão: na aba da Centi já logada, clique em Pesquisar.\" };\n    const erro = A.validarPedido(d);\n    if (erro) return { ok: false, erro };\n    // A MESMA sequência da tela ao anexar: abre o protocolo e, depois, obtém o tipo pelo LoadObjectReference (o que a\n    // tela faz ao escolher o tipo). Sem o estado da tela para isso: o tipo por load ANTES de abrir o protocolo (um load\n    // depois trocaria o protocolo aberto no servidor).\n    const porReferencia = !!entidadeDoModulo(acharClienteCenti(), A.MODULO_TIPO);\n    let tipo = porReferencia\n      ? null\n      : await apiCenti(\"GET\", `restauth/load?entity=${A.MODULO_TIPO}&key=${d.tipo}`, null, \"load do tipo\")\n          .then((t) => A.tipoDoLoad(t, d.tipo))\n          .catch(() => null);\n    const e = await abrirProtocolo(d);\n    const ja = A.jaAnexado(e, d.descricao);\n    if (ja) return { ok: true, jaAnexado: true, ...ja };\n    if (porReferencia) tipo = await tipoPorReferencia(d).catch(() => null);\n    const origemTipo = tipo ? (porReferencia ? \"referência da tela\" : \"load\") : \"sem o registro do tipo\";\n    const corpo = A.montarSalvar(e, d, new Date(), crypto.randomUUID(), tipo);\n    let conf;\n    try {\n      conf = await apiCenti(\"POST\", \"restauth/confirmsave\", A.corpoConfirmar(corpo), \"confirmsave\", true, urlsSalvar.confirmsave || \"restauth/confirmsave\");\n    } catch (err) {\n      throw new Error(`${err?.message || \"Falha no confirmsave.\"} [tipo: ${origemTipo}]`);\n    }\n    // Como a tela: a Centi pedindo confirmação → a pergunta vai ao ADM; só com o \"sim\" dele (`aceitar`) segue ao save.\n    if (conf.Confirm === true && d.aceitar !== true) return { ok: false, confirmar: A.mensagens(conf.Message) || \"A Centi pede confirmação para salvar.\" };\n    const salvo = A.conferirSalvo(await apiCenti(\"POST\", \"restauth/save\", corpo, \"save\", true, urlsSalvar.save || \"restauth/save\"), d);\n    return salvo.erro ? { ok: false, erro: salvo.erro } : { ok: true, ...salvo };\n  }\n\n  const ACOES = { pedir, protocolo, anexar };\n  window.addEventListener(\"message\", async (e) => {\n    if (e.source !== window || e.data?.fonte !== \"pca-centi-pedido\" || e.data.p !== PROTOCOLO) return;\n    const { id, acao, dados } = e.data;\n    let resposta;\n    try {\n      resposta =\n        acao === \"estado\"\n          ? { ok: true, logado: !!cabecalhos, entidade: entidadeAtual(), operacao: operacaoTela }\n          : Object.hasOwn(ACOES, acao)\n            ? await ACOES[acao](dados)\n            : { ok: false, erro: \"Ação desconhecida.\" };\n    } catch (err) {\n      resposta = { ok: false, erro: err?.message || \"Falha no pedido à Centi.\" };\n    }\n    window.postMessage({ fonte: \"pca-centi-resposta\", p: PROTOCOLO, id, resposta }, location.origin);\n  });\n})();\n",
  "centi-ponte.js": "// Ponte na aba da Centi: extensão <-> script da página (centi-main.js, que usa a sessão da Centi).\n(() => {\n  // Protocolo da conversa com o script da página (centi-main.js): só muda se o formato das mensagens mudar.\n  const P = 26;\n  const MARCA = `__pcaCentiPonte_p${P}`;\n  if (window[MARCA]) return;\n  window[MARCA] = true;\n  let seq = 0;\n  const pendentes = new Map();\n  window.addEventListener(\"message\", (e) => {\n    if (e.source !== window || e.data?.fonte !== \"pca-centi-resposta\" || e.data.p !== P) return;\n    const p = pendentes.get(e.data.id);\n    if (p) {\n      pendentes.delete(e.data.id);\n      clearTimeout(p.t);\n      p.f(e.data.resposta);\n    }\n  });\n  chrome.runtime.onMessage.addListener((msg, _sender, responder) => {\n    if (msg?.alvo !== \"centi\") return false;\n    const id = ++seq;\n    // Sem resposta do script da página → falha clara, nunca espera infinita.\n    const t = setTimeout(() => {\n      pendentes.delete(id);\n      responder({ ok: false, erro: \"A aba da Centi não respondeu — aperte F5 nela.\" });\n    }, msg.acao === \"estado\" ? 4000 : 300000);\n    pendentes.set(id, { f: responder, t });\n    window.postMessage({ fonte: \"pca-centi-pedido\", p: P, id, acao: msg.acao, dados: msg.dados }, window.location.origin);\n    return true;\n  });\n})();\n",
  "confirmar.html": "<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<title>Confirmar anexo na Centi</title>\n<style>\n  :root { color-scheme: light dark; --fundo: #ffffff; --texto: #18181b; --suave: #52525b; --borda: #e4e4e7; --alerta: #b45309; --botao: #18181b; --botao-texto: #ffffff; }\n  @media (prefers-color-scheme: dark) { :root { --fundo: #18181b; --texto: #fafafa; --suave: #a1a1aa; --borda: #3f3f46; --alerta: #fbbf24; --botao: #fafafa; --botao-texto: #18181b; } }\n  body { margin: 0; padding: 20px; background: var(--fundo); color: var(--texto); font: 14px/1.45 system-ui, sans-serif; }\n  h1 { font-size: 17px; margin: 0 0 4px; }\n  p { margin: 0 0 12px; color: var(--suave); }\n  dl { margin: 0 0 14px; border: 1px solid var(--borda); border-radius: 10px; padding: 10px 12px; }\n  dt { font-size: 12px; color: var(--suave); }\n  dd { margin: 0 0 8px; font-weight: 600; word-break: break-word; }\n  dd:last-child { margin-bottom: 0; }\n  .aviso { color: var(--alerta); font-size: 13px; }\n  .acoes { display: flex; gap: 8px; justify-content: flex-end; margin-top: 16px; }\n  button { min-height: 40px; padding: 0 16px; border-radius: 8px; font: inherit; font-weight: 600; cursor: pointer; border: 1px solid var(--borda); background: transparent; color: var(--texto); }\n  button.sim { background: var(--botao); color: var(--botao-texto); border-color: var(--botao); }\n</style>\n</head>\n<body>\n  <h1>Anexar ao protocolo da Centi?</h1>\n  <p>O sistema PCA pediu para gravar na Centi. Confira o protocolo antes de permitir.</p>\n  <dl>\n    <dt>Protocolo</dt><dd id=\"protocolo\"></dd>\n    <dt>Id na Centi</dt><dd id=\"id\"></dd>\n    <dt>Primeiro documento</dt><dd id=\"descricao\"></dd>\n    <dt>Execução no sistema</dt><dd id=\"execucao\"></dd>\n  </dl>\n  <p class=\"aviso\">Cada PDF entra como um documento NOVO. Nada do protocolo é alterado ou excluído. Vale para os documentos desta execução neste protocolo.</p>\n  <div class=\"acoes\">\n    <button id=\"nao\" type=\"button\">Recusar</button>\n    <button id=\"sim\" class=\"sim\" type=\"button\">Permitir</button>\n  </div>\n  <script src=\"confirmar.js\"></script>\n</body>\n</html>\n",
  "confirmar.js": "// Janela de confirmação da escrita na Centi (página da PRÓPRIA extensão — a página do sistema não a alcança). Mostra o\n// alvo autorizado e devolve a resposta ao serviço da extensão.\n(() => {\n  const q = new URLSearchParams(location.search);\n  const pedido = q.get(\"pedido\") ?? \"\";\n  const ano = q.get(\"ano\");\n  document.getElementById(\"protocolo\").textContent = `${q.get(\"numero\") ?? \"\"}${ano ? `/${ano}` : \"\"}`;\n  document.getElementById(\"id\").textContent = q.get(\"id\") ?? \"\";\n  document.getElementById(\"descricao\").textContent = q.get(\"descricao\") ?? \"\";\n  document.getElementById(\"execucao\").textContent = `nº ${q.get(\"execucao\") ?? \"\"}`;\n  const responder = (sim) => chrome.runtime.sendMessage({ tipo: \"confirmacao\", pedido, sim }).finally(() => window.close());\n  document.getElementById(\"sim\").addEventListener(\"click\", () => responder(true));\n  document.getElementById(\"nao\").addEventListener(\"click\", () => responder(false));\n  document.addEventListener(\"keydown\", (e) => {\n    if (e.key === \"Escape\") responder(false);\n  });\n  document.getElementById(\"nao\").focus();\n})();\n",
  "manifest.json": "{\n  \"manifest_version\": 3,\n  \"name\": \"PCA Rio Verde · Automação Centi\",\n  \"version\": \"1.4.0\",\n  \"description\": \"Canal entre a aba Automação do sistema PCA e a Centi já aberta (sessão da aba). Emite DFDs (sem vincular, assinar ou enviar) e só grava um documento novo no protocolo indicado — com a autorização de uso único do sistema e a confirmação na janela da extensão.\",\n  \"background\": {\n    \"service_worker\": \"background.js\"\n  },\n  \"host_permissions\": [\n    \"https://rioverde.centi.com.br/*\"\n  ],\n  \"content_scripts\": [\n    {\n      \"matches\": [\n        \"https://rioverde.centi.com.br/*\"\n      ],\n      \"js\": [\n        \"centi-anexo.js\",\n        \"centi-main.js\"\n      ],\n      \"run_at\": \"document_start\",\n      \"world\": \"MAIN\"\n    },\n    {\n      \"matches\": [\n        \"https://rioverde.centi.com.br/*\"\n      ],\n      \"js\": [\n        \"centi-ponte.js\"\n      ],\n      \"run_at\": \"document_start\"\n    },\n    {\n      \"matches\": [\n        \"https://governarv.com.br/painel/automacao*\",\n        \"https://www.governarv.com.br/painel/automacao*\"\n      ],\n      \"js\": [\n        \"sistema-ponte.js\"\n      ],\n      \"run_at\": \"document_start\"\n    }\n  ],\n  \"permissions\": [\n    \"scripting\",\n    \"storage\"\n  ]\n}\n",
  "sistema-ponte.js": "// Ponte na aba Automação do sistema PCA: página <-> extensão. Só esta página fala com a extensão. Cada resposta leva a\n// versão: a página ignora a de uma cópia antiga (que fica na aba depois de uma atualização da extensão).\n// ESCRITA na Centi (\"anexar\") só com a AUTORIZAÇÃO DE USO ÚNICO do sistema: esta ponte (fora do alcance dos scripts da\n// página) a CONSOME no servidor para o alvo EXATO que será gravado — Id + nº + ano + descrição tirados do próprio pedido —\n// e só então leva o pedido adiante, sem o token. O serviço da extensão ainda pede a confirmação na janela dela.\n(() => {\n  const V = chrome.runtime.getManifest().version;\n  const MARCA = `__pcaSistemaPonte_${V}`;\n  if (window[MARCA]) return;\n  window[MARCA] = true;\n  const origem = window.location.origin;\n  const responder = (id, resposta) => window.postMessage({ fonte: \"pca-extensao\", v: V, id, resposta }, origem);\n  const anunciar = () => window.postMessage({ fonte: \"pca-extensao\", v: V, tipo: \"pronto\", versao: V }, origem);\n  const texto = (v) => (v == null ? \"\" : String(v));\n\n  // Consome a autorização no servidor (a sessão do sistema vai pelo cookie da própria página).\n  async function consumir(dados) {\n    const a = dados?.autorizacao;\n    if (!a || typeof a.token !== \"string\") return { erro: \"Escrita sem a autorização do sistema.\" };\n    const alvo = { id: texto(dados.id), numero: texto(dados.numero), ano: dados.ano ? texto(dados.ano) : null, descricao: texto(dados.descricao) };\n    try {\n      const r = await fetch(new URL(\"/api/admin/automacao/autorizacoes/consumir\", origem), {\n        method: \"POST\",\n        credentials: \"same-origin\",\n        headers: { \"content-type\": \"application/json\" },\n        body: JSON.stringify({ token: a.token, capacidade: \"anexar\", alvo }),\n      });\n      const j = await r.json().catch(() => null);\n      if (!r.ok || !j?.ok) return { erro: `Autorização recusada pelo sistema: ${j?.error ?? `erro ${r.status}`}` };\n      return { autorizado: { execucaoId: j.execucaoId, chave: j.chave, ...alvo } };\n    } catch {\n      return { erro: \"Não consegui conferir a autorização no sistema (rede).\" };\n    }\n  }\n\n  async function levar(acao, dados) {\n    if (acao !== \"anexar\") return { acao, dados };\n    const c = await consumir(dados);\n    if (c.erro) return { resposta: { ok: false, erro: c.erro } };\n    const { autorizacao: _token, ...semToken } = dados;\n    return { acao, dados: semToken, autorizado: c.autorizado };\n  }\n\n  window.addEventListener(\"message\", (e) => {\n    if (e.source !== window || e.origin !== origem) return;\n    const m = e.data;\n    if (m?.fonte !== \"pca-automacao\") return;\n    if (m.tipo === \"ola\") return anunciar();\n    if (m.v && m.v !== V) return;\n    levar(m.acao, m.dados).then((x) => {\n      if (x.resposta) return responder(m.id, x.resposta);\n      try {\n        chrome.runtime.sendMessage({ acao: x.acao, dados: x.dados, autorizado: x.autorizado }, (resposta) => {\n          const erro = chrome.runtime.lastError;\n          responder(m.id, erro ? { ok: false, erro: erro.message } : (resposta ?? { ok: false, erro: \"Sem resposta da extensão.\" }));\n        });\n      } catch {\n        /* cópia antiga sem a extensão: a página usa a ponte nova */\n      }\n    });\n  });\n  anunciar();\n})();\n"
};
